-- Feature 38 local fixture history. Product authority is permanently unavailable here.
CREATE TABLE IF NOT EXISTS analytical_diversity_scopes (scope_hash char(64) PRIMARY KEY, operator_test_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytical_diversity_reports (root_hash char(64) PRIMARY KEY, scope_hash char(64) REFERENCES analytical_diversity_scopes(scope_hash), verdict text NOT NULL CHECK (verdict IN ('supported','exploratory','inconclusive','blocked')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION analytical_diversity_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'analytical diversity records are append-only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['analytical_diversity_scopes','analytical_diversity_reports'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass(t) AND tgname=t||'_immutable') THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION analytical_diversity_immutable()',t||'_immutable',t); END IF; END LOOP; END $$;
